        $(document).ready(function () {
            var hdnEinvAlert = $(".hdnEinvAlert").val();
            var _EWbByIRN = $(".FrstEWbbyIRn").val();
            if (_EWbByIRN == "Y") {
                $(".FrstEWbbyIRn").val("N");
                $("#EWBBYIRN").modal('show');
            }
            else {
                $(".FrstEWbbyIRn").val("N");
                $("#EWBBYIRN").modal('hide');
            }
            var hdnsandesPage = $(".hdnsandesPage").val();
            if (hdnsandesPage != "Y") {
                $('#Div2FAWrn').modal('show');
                $(".div2fahead").css('display', 'block');
                if (hdnEinvAlert != "Y") {
                    $(".diveinvAlert1").css('display', 'block');
                }
            }
            else if (hdnEinvAlert != "Y") {
                $('#Div2FAWrn').modal('show');
                $(".diveinvAlert1").css('display', 'block');
            }
        });
        function OTPEnrypt() {
            var otp = document.getElementById("txtotp").value;
            if (otp.length == 0) {
                alert("Please Enter OTP");
                return false;
            }
            var res = sha256_digest(otp);
            document.getElementById("txtotp").setAttribute("value", res);
            document.getElementById("txtotp").value = res;
            return true;
        }
    </script>
