                            <div class="flexbox mb-2 pb-1" style="border-bottom: 1px solid #ddd;">
                                <div>
                                    <h5 class="m-0 pt-1 pb-1 font-weight-bold blink2">Latest Updates </h5>
                                </div>
                                <div class="d-inline-flex">
                                    <div class="px-3" style="border-right: 1px solid rgba(0,0,0,.1);">
                                        <div>
                                            <span class="h5 m-0">31/05/2023</span>
                                        </div>
